import React, { useState } from 'react';
import { buildLinkGraph, NoteInput } from './engines/wikilinkGraph';
import { scheduleReview, CardState } from './engines/sm2Scheduler';

const INITIAL_NOTES: NoteInput[] = [
  { id: '1', title: 'Calculus', body: 'Fundamentals of [[Limits]] and [[Derivatives]].' },
  { id: '2', title: 'Limits', body: 'The foundation for [[Calculus]].' },
  { id: '3', title: 'Derivatives', body: 'Rate of change derived from [[Limits]].' },
];

export default function App() {
  const [notes] = useState<NoteInput[]>(INITIAL_NOTES);
  const [card, setCard] = useState<CardState>({ reps: 0, interval: 1, ease: 2.5 });
  const graph = buildLinkGraph(notes);

  const handleReview = (grade: number) => {
    setCard((prev) => scheduleReview(prev, grade, Date.now()));
  };

  return (
    <div className="p-6 max-w-xl mx-auto space-y-6">
      <header className="border-b border-slate-800 pb-3">
        <h1 className="text-lg font-bold text-indigo-400">MindRecall Studio</h1>
        <p className="text-xs text-slate-400">Fused Inkwell Note Graph & Recall SM-2 Spaced Repetition</p>
      </header>
      <section className="bg-slate-900 border border-slate-800 rounded p-4 text-xs">
        <h2 className="font-semibold mb-2 text-slate-300">Note Graph Connectivity</h2>
        <ul className="space-y-1">
          {graph.nodes.map((n) => (
            <li key={n.id} className="flex justify-between">
              <span>{n.title}</span>
              <span className="text-indigo-400">Degree: {n.degree}</span>
            </li>
          ))}
        </ul>
      </section>
      <section className="bg-slate-900 border border-slate-800 rounded p-4 text-xs space-y-3">
        <h2 className="font-semibold text-slate-300">Spaced Repetition Scheduler</h2>
        <div className="text-slate-400">
          Reps: {card.reps} | Interval: {card.interval}d | Ease: {card.ease.toFixed(2)}
        </div>
        <div className="flex gap-2">
          {[1, 2, 3, 4, 5].map((grade) => (
            <button
              key={grade}
              onClick={() => handleReview(grade)}
              className="px-3 py-1.5 rounded bg-indigo-600 hover:bg-indigo-500 text-white font-medium"
            >
              Grade {grade}
            </button>
          ))}
        </div>
      </section>
    </div>
  );
}
